<template>
  <el-card class="me-area" :body-style="{ padding: '16px' }">
    <div class="me-article-header">

      <a @click="view(id)" class="me-article-title">{{title}}</a>
      <el-button v-if="weight > 0" class="me-article-icon" type="text" style="color: var(--accent-color);">置顶</el-button>
      <span class="me-pull-right me-article-count">
		<i class="el-icon-message"></i>&nbsp;{{commentCounts || 0}}
	</span>
      <span class="me-pull-right me-article-count">
		<i class="el-icon-view"></i>&nbsp;{{viewCounts}}
	</span>
    </div>

    <div class="me-artile-description">
      {{summary}}
    </div>
    <div class="me-article-footer">
	<span class="me-article-author">
		<i class="el-icon-user"></i>&nbsp;{{author.nickname}}
	</span>

      <el-tag v-if="category" size="mini" type="success">{{category.categoryname}}</el-tag>
      <el-tag v-for="t in tags" :key="t.tagname" size="mini" type="primary">{{t.tagname}}</el-tag>

      <span class="me-pull-right me-article-count">
		<i class="el-icon-time"></i>&nbsp;{{createDate | format}}
	</span>

    </div>
  </el-card>
</template>

<script>
  import { formatTime } from "../../utils/time";

  export default {
    name: 'ArticleItem',
    props: {
      id: Number,
      weight: Number,
      title: String,
      commentCounts: Number,
      viewCounts: Number,
      summary: String,
      author: Object,
      category: Object,
      tags: Array,
      createDate: String
    },
    data() {
      return {}
    },
    methods: {
      view(id) {
        this.$router.push({path: `/view/${id}`})
      }
    }
  }
</script>

<style scoped>

  .me-article-header {
    padding-bottom: 10px;
    border-bottom: 1px solid var(--light-gray);
    margin-bottom: 12px;
  }

  .me-article-title {
    font-weight: 600;
    font-size: 18px;
    color: var(--secondary-color);
    transition: color 0.3s ease;
  }

  .me-article-title:hover {
    color: var(--primary-color);
  }

  .me-article-icon {
    padding: 3px 8px;
  }

  .me-article-count {
    color: var(--dark-gray);
    padding-left: 14px;
    font-size: 13px;
  }

  .me-pull-right {
    float: right;
  }

  .me-artile-description {
    font-size: 14px;
    line-height: 24px;
    margin-bottom: 12px;
    color: #333;
  }

  .me-article-footer {
    padding-top: 10px;
    border-top: 1px solid var(--light-gray);
  }

  .me-article-author {
    color: var(--dark-gray);
    padding-right: 18px;
    font-size: 13px;
  }

  .el-tag {
    margin-left: 6px;
    margin-bottom: 4px;
  }

  .el-tag--primary {
    background-color: rgba(30, 136, 229, 0.1);
    border-color: var(--primary-color);
    color: var(--primary-color);
  }

</style>



