import request from '@/request'

export function getAllTags() {
  return request({
    url: '/tags',
    method: 'get',
  })
}

export function getTags() {
  return request({
    url: '/tags',
    method: 'get',
  })
}

export function getAllTagsDetail() {
  return request({
    url: '/tags/detail',
    method: 'get',
  })
}

export function getHotTags() {
  return request({
    url: '/tags/hot',
    method: 'get',
  })
}

export function getTag(id) {
  return request({
    url: `/tags/${id}`,
    method: 'get',
  })
}

export function getTagDetail(id) {
  return request({
    url: `/tags/detail/${id}`,
    method: 'get',
  })
}

export function saveTag(tag) {
  if (tag.id) {
    return request({
      url: '/tags/update',
      method: 'post',
      data: tag
    })
  } else {
    return request({
      url: '/tags/create',
      method: 'post',
      data: tag
    })
  }
}

export function deleteTag(id) {
  return request({
    url: `/tags/delete/${id}`,
    method: 'get'
  })
}



