import request from '@/request'


export function getArticles(query, page) {
  console.log('getArticles query:', JSON.stringify(query))
  let params = {
    pageNumber: page.pageNumber,
    pageSize: page.pageSize,
    name: page.name,
    sort: page.sort
  }
  if (query && query.year !== undefined && query.year !== null) params.year = query.year
  if (query && query.month !== undefined && query.month !== null) params.month = query.month
  if (query && query.tagId !== undefined && query.tagId !== null) params.tagId = query.tagId
  if (query && query.categoryId !== undefined && query.categoryId !== null && query.categoryId !== 0) params.categoryId = query.categoryId
  if (query && query.keyword !== undefined && query.keyword !== null && query.keyword.trim() !== '') params.keyword = query.keyword.trim()
  console.log('getArticles params:', JSON.stringify(params))
  return request({
    url: '/articles',
    method: 'get',
    params: params
  })
}

export function getHotArtices() {
  return request({
    url: '/articles/hot',
    method: 'get'
  })
}

export function getNewArtices() {
  return request({
    url: '/articles/new',
    method: 'get'
  })
}

export function viewArticle(id) {
  return request({
    url: `/articles/view/${id}`,
    method: 'get'
  })
}

export function getArticlesByCategory(id) {
  return request({
    url: `/articles/category/${id}`,
    method: 'get'
  })
}

export function getArticlesByTag(id) {
  return request({
    url: `/articles/tag/${id}`,
    method: 'get'
  })
}


export function publishArticle(article) {
  return request({
    url: '/articles/publish',
    method: 'post',
    data: article
  })
}

export function listArchives() {
  return request({
    url: '/articles/listArchives',
    method: 'get'
  })
}

export function getArticleById(id) {
  return request({
    url: `/articles/${id}`,
    method: 'get'
  })
}

export function deleteArticle(id) {
  return request({
    url: `/articles/delete/${id}`,
    method: 'get'
  })
}

export function saveDraft(article) {
  return request({
    url: '/articles/draft',
    method: 'post',
    data: article
  })
}

export function getDrafts() {
  return request({
    url: '/articles/drafts',
    method: 'get'
  })
}



