import request from '@/request'

export function getAllCategorys() {
  return request({
    url: '/categorys',
    method: 'get',
  })
}

export function getCategorys() {
  return request({
    url: '/categorys',
    method: 'get',
  })
}

export function getAllCategorysDetail() {
  return request({
    url: '/categorys/detail',
    method: 'get',
  })
}

export function getCategory(id) {
  return request({
    url: `/categorys/${id}`,
    method: 'get',
  })
}

export function getCategoryDetail(id) {
  return request({
    url: `/categorys/detail/${id}`,
    method: 'get',
  })
}

export function saveCategory(category) {
  if (category.id) {
    return request({
      url: '/categorys/update',
      method: 'post',
      data: category
    })
  } else {
    return request({
      url: '/categorys/create',
      method: 'post',
      data: category
    })
  }
}

export function deleteCategory(id) {
  return request({
    url: `/categorys/delete/${id}`,
    method: 'get'
  })
}



